  },
  {
    "id": 272,
    "text": "うどん始めてます。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 273,
    "text": "実は昨日の夜もうどんを食べました。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 274,
    "text": "嬉しいです。",
    "diarized": "Machico"
  },
  {
    "id": 275,
    "text": "温かいのも冷たいのも。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 276,
    "text": "いや、両方いいよね。",
    "diarized": "Machico"
  },
  {
    "id": 277,
    "text": "夏といえば。",
    "diarized": "Machico"
  },
  {
    "id": 278,
    "text": "どっちも食べられちゃう。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 279,
    "text": "美味しいんですよね。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 280,
    "text": "うどんはさ、私絶対なんか海外へ行って行く時にさ、絶対空港でうどんを食べていくんだよ。",
    "diarized": "Machico"
  },
  {
    "id": 281,
    "text": "やっぱ",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 282,
    "text": "ジャパニーズだしをさ摂取してから海外に行きたい。",
    "diarized": "Machico"
  },
  {
    "id": 283,
    "text": "確かに。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 284,
    "text": "確かに日本の味ですもんね。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 285,
    "text": "そうそうそうやっぱ食べやすいしね、朝っぱらからでも。",
    "diarized": "Machico"
  },
  {
    "id": 286,
    "text": "あの、地元福岡だとうどんが結構有名で。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 287,
    "text": "え、福岡のうどんはちょっと柔らかいんだよ。",
    "diarized": "Machico"
  },
  {
    "id": 288,
    "text": "柔らかいです。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 289,
    "text": "そっかそっか柔らかいな。",
    "diarized": "Machico"
  },
  {
    "id": 290,
    "text": "もう食べたくなるんですよ、無性に福岡のうどんが。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 291,
    "text": "え、やっぱりこっちで食べる時も福岡のうどんを取り寄せたりすんだ?",
    "diarized": "Machico"
  },
  {
    "id": 292,
    "text": "しますします。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 293,
    "text": "結構して。",
    "diarized": "Ruriko Noguchi"
  }
]

