  },
  {
    "id": 299,
    "text": "あれがやっぱ美味しい。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 300,
    "text": "いつだって食べたい。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 301,
    "text": "いや、いいな。",
    "diarized": "Machico"
  },
  {
    "id": 302,
    "text": "食べたい。",
    "diarized": "Machico"
  },
  {
    "id": 303,
    "text": "お腹空いてきましたね。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 304,
    "text": "ね。",
    "diarized": "Machico"
  },
  {
    "id": 305,
    "text": "こんな時間に今ちょっとね、我々の収録タイムお腹が空く時間ということで。",
    "diarized": "Machico"
  },
  {
    "id": 306,
    "text": "そう。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 307,
    "text": "いい食欲増進でございます。",
    "diarized": "Machico"
  },
  {
    "id": 308,
    "text": "いいでございますね。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 309,
    "text": "はあ。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 310,
    "text": "じゃ、ここでおたよりは以上ということで皆さんありがとうございました。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 311,
    "text": "ありがとうございます。",
    "diarized": "Machico"
  },
  {
    "id": 312,
    "text": "こんな感じでね、我々プロセカキャストに聞いてみたい質問やテーマもお待ちしておりますよ。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 313,
    "text": "はい。",
    "diarized": "Machico"
  },
  {
    "id": 314,
    "text": "ということでここで1曲お届けいたします。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 315,
    "text": "え、こちらの曲はうかろくさんに書いていただきました。",
    "diarized": "Ruriko Noguchi"
  }
]

