  },
  {
    "id": 317,
    "text": "それではお聞きください。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 318,
    "text": "天秤指先で触れて。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 319,
    "text": "努力すれば強く願えばどちらもなせる気でいた。",
    "diarized": "2"
  },
  {
    "id": 320,
    "text": "あにたけの時間のせいを払うけど単位なって私が触れたら賢かったら時が止まってくれたらえ、",
    "diarized": "2"
  },
  {
    "id": 321,
    "text": "空と書いて現実逃避自分に言い訳だそうな。",
    "diarized": "2"
  },
  {
    "id": 322,
    "text": "望みが遠ざかってしまう。",
    "diarized": "2"
  },
  {
    "id": 323,
    "text": "いやだよ。",
    "diarized": "2"
  },
  {
    "id": 324,
    "text": "いやだ追ってかないで。",
    "diarized": "2"
  },
  {
    "id": 325,
    "text": "ふたかから注がれてく世界を淀ませないようにまだ抗ってた。",
    "diarized": "2"
  },
  {
    "id": 326,
    "text": "回らない。",
    "diarized": "2"
  },
  {
    "id": 327,
    "text": "バルブを回して大丈夫と繰り返し私に暗示を施した。",
    "diarized": "2"
  },
  {
    "id": 328,
    "text": "決められない決めたくないどちらも大事なんだから決めなくちゃ選ばなきゃそんなの分かってるも。",
    "diarized": "2"
  },
  {
    "id": 329,
    "text": "答えられなくて閉じ込めてごめんねと小さく",
    "diarized": "2"
  },
  {
    "id": 330,
    "text": "告げる",
    "diarized": "2"
  },
  {
    "id": 331,
    "text": "流れのままに濁ってく世界は詰えながら心までたどるぬく",
    "diarized": "2"
  },
  {
    "id": 332,
    "text": "かわで世界と私を見てた。",
    "diarized": "2"
  },
  {
    "id": 333,
    "text": "目をそらしこれで良かったのと呟いた。",
    "diarized": "2"
  },
  {
    "id": 334,
    "text": "良かったんだよ。",
    "diarized": "2"
  },
  {
    "id": 335,
    "text": "セカラじ。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 336,
    "text": "今回はこんなテーマでメールを募集しました。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 337,
    "text": "おうち時間の過ごし方。",
    "diarized": "Ruriko Noguchi"
  }
