    "text": "かいけつゾロリとか。",
    "diarized": "Machico"
  },
  {
    "id": 393,
    "text": "絵が描いてま、面白いんですよね。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 394,
    "text": "やっぱ結局ね。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 395,
    "text": "いっぱいこまったさんわかったさんの料理のやつとか。",
    "diarized": "Machico"
  },
  {
    "id": 396,
    "text": "分かります。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 397,
    "text": "児童用の図書ってやっぱ面白いんですよね。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 398,
    "text": "あれがやっぱりね。",
    "diarized": "Machico"
  },
  {
    "id": 399,
    "text": "印象に残って。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 400,
    "text": "懐かしい。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 401,
    "text": "じゃんたんのあんまり挿絵のない本とか読むのはやっぱ難しくて。",
    "diarized": "Machico"
  },
  {
    "id": 402,
    "text": "あ、ま、ま、集中力もね、必要ですしね。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 403,
    "text": "だから本当今よくこういう仕事してるなって思う。",
    "diarized": "Machico"
  }
