    "diarized": "2"
  },
  {
    "id": 449,
    "text": "ドラム?",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 450,
    "text": "かっこいい!",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 451,
    "text": "ほなみと一緒だ。",
    "diarized": "Machico"
  },
  {
    "id": 452,
    "text": "ほなちゃんと一緒だ。",
    "diarized": "Machico"
  },
  {
    "id": 453,
    "text": "凄い!",
    "diarized": "2"
  },
  {
    "id": 454,
    "text": "もう超夏の思い出ですね。",
    "diarized": "2"
  },
  {
    "id": 455,
    "text": "ういい思い出になるよ、これをやりとげた時は。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 456,
    "text": "いや、本当羨ましい。",
    "diarized": "2"
  },
  {
    "id": 457,
    "text": "青春だ。",
    "diarized": "2"
  },
  {
    "id": 458,
    "text": "いや、いいね。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 459,
    "text": "しかもこんな掛け持ちで?",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 460,
    "text": "確かに、超忙しい。",
    "diarized": "2"
  },
  {
    "id": 461,
    "text": "そりゃ忙しいよ、夏休みどころじゃないね。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 462,
    "text": "浪人の夏休みでその、うわ、",
    "diarized": "2"
  },
  {
    "id": 463,
    "text": "かっこいい。",
    "diarized": "2"
  },
  {
    "id": 464,
    "text": "いいなあ、いっぱい写真撮りなね。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 465,
    "text": "ムービーも撮って。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 466,
    "text": "絶対ムービーに残して。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 467,
    "text": "絶対にね。",
    "diarized": "2"
  },
  {
    "id": 468,
    "text": "なんかもうさあ、なんかうちの学生の時はやっぱガラケーだったし、",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 469,
    "text": "はいはいはい。",
    "diarized": "Ruriko Noguchi"
  }
]

