  },
  {
    "id": 528,
    "text": "絵のデザインも、",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 529,
    "text": "お洋服のデザインもうん。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 530,
    "text": "はまったんだ。",
    "diarized": "2"
  },
  {
    "id": 531,
    "text": "いや、本当になん、このセカラジで何度も言ってるんですけど、絵を描ける人を本当に尊敬しておりまして。",
    "diarized": "2"
  },
  {
    "id": 532,
    "text": "そんなに得意ではない?",
