  },
  {
    "id": 587,
    "text": "じゃあ、続きます。",
    "diarized": "Machico"
  },
  {
    "id": 588,
    "text": "はい。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 589,
    "text": "ラジオネームCちゃん大好きJKさんからいただきました。",
    "diarized": "2"
  },
  {
    "id": 590,
    "text": "ありがとうございます。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 591,
    "text": "ありがとうございます。",
    "diarized": "2"
  },
  {
    "id": 592,
    "text": "野口さん、Machikoさん、コンワンダホイ。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 593,
    "text": "コンワンダホイ。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 594,
    "text": "コンワンダホイ。",
    "diarized": "2"
  },
  {
    "id": 595,
    "text": "はい、初めてのお頼り失礼いたします。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 596,
    "text": "はいはい。",
    "diarized": "2"
  },
  {
    "id": 597,
    "text": "私のおうち時間の過ごし方は、ずばり作曲だったり歌ったりしています。",
