  {
    "id": 625,
    "text": "いや、分かります。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 626,
    "text": "私もなんかずっと、",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 627,
    "text": "なんかの教科の教科書なくして延々と他のクラスから借りてたの。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 628,
    "text": "そんなことが予防できるだったらタブレットが絶対にいいよ。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 629,
    "text": "確かに。",
    "diarized": "2"
  },
  {
    "id": 630,
    "text": "もう絶対持って帰れみたいな時もありましたけど。",
    "diarized": "2"
  },
  {
    "id": 631,
    "text": "重い重いよ。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 632,
    "text": "私はもうもう没収されても置いて帰ってた。",
    "diarized": "2"
  },
  {
    "id": 633,
    "text": "置き弁って言ってました。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 634,
    "text": "置き弁って言ってました。",
    "diarized": "2"
  },
  {
    "id": 635,
    "text": "そんなことないのかしら、タブレットだと。",
    "diarized": "2"
  },
  {
    "id": 636,
    "text": "いや、ないんじゃない、もう。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 637,
    "text": "面白い。",
    "diarized": "2"
  },
  {
    "id": 638,
    "text": "凄いですね。",
    "diarized": "2"
  },
  {
    "id": 639,
    "text": "曲を作ったり歌の練習。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 640,
    "text": "うわあ、いいなあ。",
    "diarized": "2"
  },
  {
    "id": 641,
    "text": "え、でもさ、なんかその歌の練習とかこれからレベルアップしていくって中でさ、",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 642,
    "text": "もちろん基礎は大切だと思うの、腹式。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 643,
    "text": "気をつけなきゃとかさ、なんかこういうところって言うよりかは、",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 644,
    "text": "今は楽しくさ、自分がどの状態で気持ちよく歌えるかって言うところを固めていって、",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 645,
    "text": "そこから腹式だったりをサブで考えた方がもしかしたら自由に歌が歌えるんじゃないかな。",
    "diarized": "Ruriko Noguchi"
  }
]

