  },
  {
    "id": 657,
    "text": "本当に音楽が好きなんだね。",
    "diarized": "2"
  },
  {
    "id": 658,
    "text": "曲を作ったりさあ。",
    "diarized": "2"
  },
  {
    "id": 659,
    "text": "ええ。",
    "diarized": "2"
  },
  {
    "id": 660,
    "text": "高校生だよ。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 661,
    "text": "ええ、何してたんだろう、私は一体。",
