  },
  {
    "id": 681,
    "text": "なんか凄い、いっつも凄い。",
    "diarized": "2"
  },
  {
    "id": 682,
    "text": "想像力が豊かと言うか。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 683,
    "text": "確かに。",
    "diarized": "2"
  },
  {
    "id": 684,
    "text": "コントとかもやっぱ面白いですよね。",
    "diarized": "2"
  },
  {
    "id": 685,
    "text": "演技力ない。",
    "diarized": "2"
  },
  {
    "id": 686,
    "text": "テンポ感とか凄い独特だから。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 687,
    "text": "好きだったな。",
    "diarized": "2"
  },
  {
    "id": 688,
    "text": "え、確かにそういうのやっぱりアウトプット、インプットだね。",
