  },
  {
    "id": 715,
    "text": "ああ、やっぱりなんかプロセカって本当にストーリーがさ、しっかりそのたくさん描いてくださるじゃない。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 716,
    "text": "そうなんですよね。",
    "diarized": "2"
  },
  {
    "id": 717,
    "text": "だから読みごたえあるよね。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 718,
    "text": "どのユニットもまた全然違う物語が濃厚なものが繰り広げられているから。",
    "diarized": "2"
  },
  {
    "id": 719,
    "text": "いや、凄いよっすよね、ストーリー。",
    "diarized": "2"
  },
  {
    "id": 720,
    "text": "存分に楽しんでいただきたい。",
    "diarized": "2"
  },
  {
    "id": 721,
    "text": "しかも過去のも見れるしね。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 722,
    "text": "そうなんですよ。",
    "diarized": "2"
  },
  {
    "id": 723,
    "text": "ありがたいよね。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 724,
    "text": "最近始めても昔からやってても。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 725,
    "text": "そうですよね。",
    "diarized": "2"
  },
  {
    "id": 726,
    "text": "うん。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 727,
    "text": "ああ、嬉しいなあ。",
    "diarized": "2"
  },
  {
    "id": 728,
    "text": "我々も収録した甲斐があります。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 729,
    "text": "いや、本当そうなんです。",
    "diarized": "2"
  },
  {
    "id": 730,
    "text": "なんか誰かが読んでくれているんだっていう",
    "diarized": "2"
  },
  {
    "id": 731,
    "text": "嬉しくなっちゃう。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 732,
    "text": "一生懸命お芝居をして。",
    "diarized": "2"
  },
  {
    "id": 733,
    "text": "だってプロセカってさ、結構その歌の収録もさ、セリフの収録もさ、",
    "diarized": "Ruriko Noguchi"
  }
]

