  },
  {
    "id": 745,
    "text": "感じています。",
    "diarized": "2"
  },
  {
    "id": 746,
    "text": "これからも頑張って。",
    "diarized": "2"
  },
  {
    "id": 747,
    "text": "頑張って演じますね。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 748,
    "text": "歌ったり演じたりしていきたいと思います。",
    "diarized": "2"
  },
  {
    "id": 749,
    "text": "受け取ってください。",
    "diarized": "Ruriko Noguchi"
  },
  {
    "id": 750,
    "text": "ありがとうございます。",
    "diarized": "2"
  },
  {
    "id": 751,
    "text": "ではということで、今回のご紹介は以上です。",
    "diarized": "2"
  },
  {
    "id": 752,
    "text": "たくさんのお頼りありがとうございました。",
    "diarized": "2"
  },
  {
    "id": 753,
